"""Checks the Objects filters of the map (allied / enemy) and the radar of the fixed stations with the owners of the scenario file. Needs tests/fixtures/saves/Save3.cam and beartrap/PSI_BEAR_TRAP_26-double.cam. Usage: python3 tools/objects-test.py"""
import base64, subprocess, sys, time, os
from playwright.sync_api import sync_playwright
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FX = R + '/tests/fixtures/'
srv = subprocess.Popen([sys.executable, R + '/tools/serve.py', '8796', '--directory', R], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
ok = True
def check(n, c):
    global ok; ok &= bool(c); print('OK  ' if c else 'FAIL', n)
b64 = lambda p: base64.b64encode(open(p, 'rb').read()).decode()
try:
    with sync_playwright() as p:
        br = p.chromium.launch(); pg = br.new_page(viewport={'width': 1500, 'height': 1000}, reduced_motion='reduce'); errs = []
        pg.on('pageerror', lambda e: errs.append(str(e)))
        pg.goto('http://localhost:8796/app/index.html'); pg.wait_for_timeout(1000)
        pg.evaluate("async(b)=>{await __app.loadCam(new File([Uint8Array.from(atob(b),c=>c.charCodeAt(0))],'x.cam'))}", b64(FX + 'beartrap/PSI_BEAR_TRAP_26-double.cam')); pg.wait_for_timeout(1200)
        n = pg.evaluate("b=>__app.initialOwners(Uint8Array.from(atob(b),c=>c.charCodeAt(0)))", b64(FX + 'saves/Save3.cam'))
        check('the scenario file gives the owner of every objective', n == 5999)
        # one objective of each kind: ours, an ally's, an enemy's, one nobody knows
        own = pg.evaluate("()=>{const C=__app.ST.C,v=C.playerTeam,m=C.objOwn,al=[],en=[],ne=[],S=C.stance;m.forEach((o,k)=>{if(o==v)al.push(k);else if(o&&S&&(S[v][o]==1||S[o][v]==1||S[v][o]==2||S[o][v]==2))al.push(k);else if(o&&S&&[S[v][o],S[o][v]].some(x=>x==0||x==4||x==5))en.push(k);else if(o)ne.push(k)});return {a:al[0],e:en[0],n:ne[0],team:v}}")
        check('there are allied, enemy and neutral objectives in the scenario (neutral: relation 3, the teams of China and Russia)', own['a'] is not None and own['e'] is not None and own['n'] is not None)
        ab = pg.evaluate("()=>{const C=__app.ST.C,v=C.playerTeam,S=C.stance,r={a:null,e:null};for(const o of C.D.ob){if(!C.D.ab[o[0]]||!C.objOwn.has(o[0]))continue;const w=C.objOwn.get(o[0]);if(!w)continue;const al=w==v||S[v][w]==1||S[w][v]==1||S[v][w]==2||S[w][v]==2,en=[S[v][w],S[w][v]].some(x=>x==0||x==4||x==5);if(al&&!r.a)r.a=o;if(!al&&en&&!r.e)r.e=o}return r}")
        pg.click('[data-t=mp]'); pg.wait_for_selector('#mpmap .leaflet-pane', state='attached', timeout=8000); pg.wait_for_timeout(700)
        pg.evaluate("o=>{window.__targetData={objectives:async()=>[{id:o.a,name:'Ally Plant',type:20,n:2875827,e:2293401,ocd:985},{id:o.e,name:'Enemy Plant',type:20,n:2800000,e:2200000,ocd:986},{id:o.n,name:'Neutral Plant',type:20,n:2750000,e:2230000,ocd:986},{id:999999,name:'Unknown Plant',type:20,n:2700000,e:2250000,ocd:986},{id:o.a,name:'Ally City',type:8,n:2860000,e:2290000,ocd:987},{id:o.e,name:'Enemy Town',type:28,n:2810000,e:2210000,ocd:988},{id:999998,name:'Free Village',type:29,n:2760000,e:2240000,ocd:989},...[[o.ab_a,2],[o.ab_e,1]].map(([x,t])=>({id:x[0],name:x[1],type:t,n:x[3]*3280.84,e:x[2]*3280.84,ocd:1}))],features:async x=>[]}}", {**own, 'ab_a': ab['a'], 'ab_e': ab['e']})
        secs = pg.evaluate("()=>[...document.querySelectorAll('#mpbar .mps')].map(e=>e.dataset.sec)")
        check('one macro filter Objects below Display (no Allied / Enemy / Neutral split), the Names switch comes last', 'Objects' in secs and secs.index('Display') < secs.index('Objects') and not any(x in secs for x in ('Allied objects', 'Enemy objects', 'Neutral objects')) and pg.evaluate("()=>{const r=[...document.querySelectorAll('#mpbar label.mpr')];const l=r[r.length-1];return !!l.querySelector('input[data-k=names]')}"))
        pg.evaluate("()=>{const m=document.querySelector('#mpbar input.mst[data-sec=Objects]');m.checked=true;m.dispatchEvent(new Event('change',{bubbles:true}))}"); pg.wait_for_timeout(300)
        check('the Objects master switch turns every object layer on, and off again', pg.evaluate("()=>['o20','o1','o2'].every(k=>document.querySelector('#mpfilw input[data-k='+k+']').checked)"))
        pg.evaluate("()=>{const m=document.querySelector('#mpbar input.mst[data-sec=Objects]');m.checked=false;m.dispatchEvent(new Event('change',{bubbles:true}))}"); pg.wait_for_timeout(300)
        check('...off', pg.evaluate("()=>['o20','o1','o2'].every(k=>!document.querySelector('#mpfilw input[data-k='+k+']').checked)"))
        tog = lambda k, v: pg.evaluate("([k,v])=>{const c=document.querySelector('#mpfilw input[data-k='+k+']');if(c.checked!=v){c.checked=v;c.dispatchEvent(new Event('change',{bubbles:true}))}}", [k, v])
        # the dots (one element each) and the political places (on the canvas: a circle with its tooltip text in the options)
        names = lambda: sorted(pg.evaluate("()=>{const r=[];__app.mapV.leaflet.eachLayer(l=>{if(l.options&&l.options.icon&&/nobj( |$)/.test(l.options.icon.options.className||'')&&!/ sub/.test(l.options.icon.options.className)&&l._map&&l._tooltip)r.push(l._tooltip._content.split(' · ')[0]);else if(l.options&&l.options.halo&&l._map)r.push(l.options.tip.split(' · ')[0])});return r}"))
        tog('o20', True); pg.wait_for_timeout(800)
        check('one switch per type: all four plants (allied, enemy, neutral, owner not known)', names() == ['Ally Plant', 'Enemy Plant', 'Neutral Plant', 'Unknown Plant'])
        tip = pg.evaluate("()=>{let t='';__app.mapV.leaflet.eachLayer(l=>{if(l._tooltip&&/Enemy Plant/.test(l._tooltip._content))t=l._tooltip._content});return t}")
        check('the tooltip names the team that owns the objective', 'Enemy Plant' in tip and tip.count(' · ') >= 2)
        ring = lambda: pg.evaluate("()=>{const r={};__app.mapV.leaflet.eachLayer(l=>{if(l.options&&l.options.icon&&/nobj( |$)/.test(l.options.icon.options.className||'')&&!/ sub/.test(l.options.icon.options.className)&&l._map&&l._tooltip){const i=l._icon.querySelector('i'),cs=getComputedStyle(i);r[l._tooltip._content.split(' \u00b7 ')[0]]={cls:i.className,bg:cs.backgroundColor,sh:cs.boxShadow}}});return r}")
        r0 = ring()
        check('owner colouring is off by default: no ring on any dot', all('none' in v['sh'] or 'rgb(255, 255, 255) 0px 0px 0px 1.5px' not in v['sh'] and 'rgb(255, 93, 93)' not in v['sh'] for v in r0.values()))
        pg.evaluate("()=>document.querySelector('#mpocol').click()"); pg.wait_for_timeout(300)
        r1 = ring()
        check('colour by owner: only the allied and the enemy dot get a ring (neutral / unknown stay as they are)', 'oa' in r1['Ally Plant']['cls'].split() and 'oe' in r1['Enemy Plant']['cls'].split() and not any(c in r1['Neutral Plant']['cls'].split() + r1['Unknown Plant']['cls'].split() for c in ('oa', 'oe')) and r1['Neutral Plant']['sh'] == r0['Neutral Plant']['sh'] and 'rgb(255, 93, 93)' in r1['Enemy Plant']['sh'])
        check('the fill (intact / damaged / destroyed) is untouched by the owner colouring', all(r0[k]['bg'] == r1[k]['bg'] for k in r0))
        pg.evaluate("()=>document.querySelector('#mpocol').click()"); pg.wait_for_timeout(200)
        op = pg.evaluate("()=>{const r=document.querySelector('#mpbar .mpo'),f=document.querySelector('#mpobj');r.click();return f.style.display!='none'}"); pg.evaluate("()=>document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}))"); pg.wait_for_timeout(300)
        check('the side panel opens from the Objects row and closes with Escape', op and pg.evaluate("()=>document.querySelector('#mpobj').style.display=='none'"))
        pg.emulate_media(reduced_motion='no-preference')
        check('whatever is shown again fades in (menus, panels, pages)', pg.evaluate("async()=>{const d=document.createElement('div');d.style.display='none';document.body.append(d);await Promise.resolve();d.style.display='';await new Promise(r=>setTimeout(r,30));const n=d.getAnimations().length;d.remove();return n}") > 0)
        pg.emulate_media(reduced_motion='reduce')
        check('the side panel bottom lines up with the bottom of the filter menu', pg.evaluate("()=>{const m=document.querySelector('#mpbar');if(getComputedStyle(m).display=='none')document.querySelector('#mpfilb').click();const r=document.querySelector('#mpbar .mpo'),f=document.querySelector('#mpobj');r.click();const d=Math.abs(f.getBoundingClientRect().bottom-document.querySelector('#mpbar').getBoundingClientRect().bottom);document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}));return d<2}"))
        pg.wait_for_timeout(300)
        tog('o20', False); pg.wait_for_timeout(600)
        check('off: nothing is drawn', names() == [])
        # the political layer (cities, towns, villages): a block of the Objects panel, off by default, not touched by the Objects switches, three sizes, the owner ring, no buildings
        pol = lambda: pg.evaluate("()=>['o8','o28','o29'].map(k=>document.querySelector('#mpobj input[data-k='+k+']')).map(c=>c&&c.checked)")
        check('a Political block in the side panel of the Objects (Cities, Towns, Villages), all off; no section of its own in the menu %s' % pol(), pol() == [False] * 3 and 'Political' not in secs and 'Places' not in secs and pg.evaluate("()=>document.querySelector('#mpobj .mpps b').textContent") == 'Political')
        check('one all / none button that says what it does (all)', pg.evaluate("()=>document.querySelector('#mpobj a[data-a=tog]').textContent") == 'all')
        pg.evaluate("()=>{const m=document.querySelector('#mpbar input.mst[data-sec=Objects]');m.checked=true;m.dispatchEvent(new Event('change',{bubbles:true}))}"); pg.wait_for_timeout(500)
        check('the Objects switch (all) leaves the Political layer off', pol() == [False] * 3 and 'Ally City' not in names())
        pg.evaluate("()=>{const m=document.querySelector('#mpbar input.mst[data-sec=Objects]');m.checked=false;m.dispatchEvent(new Event('change',{bubbles:true}))}"); pg.wait_for_timeout(300)
        pg.evaluate("()=>document.querySelector('#mpobj a[data-a=tog]').click()"); pg.wait_for_timeout(300)
        check('the all / none button turns the objects on and says none; the Political layer stays off', pg.evaluate("()=>document.querySelector('#mpobj a[data-a=tog]').textContent") == 'none' and pol() == [False] * 3 and pg.evaluate("()=>['o20','o1','o2'].every(k=>document.querySelector('#mpfilw input[data-k='+k+']').checked)"))
        pg.evaluate("()=>document.querySelector('#mpobj a[data-a=tog]').click()"); pg.wait_for_timeout(300)
        check('...and off again (all)', pg.evaluate("()=>document.querySelector('#mpobj a[data-a=tog]').textContent") == 'all' and pg.evaluate("()=>['o20','o1','o2'].every(k=>!document.querySelector('#mpfilw input[data-k='+k+']').checked)"))
        pg.evaluate("()=>document.querySelector('#mpobj a[data-a=pol]').click()"); pg.wait_for_timeout(800)
        check('the political button turns only the three political layers on', pol() == [True] * 3 and pg.evaluate("()=>document.querySelector('#mpobj a[data-a=pol]').classList.contains('on')") and pg.evaluate("()=>['o20','o1','o2'].every(k=>!document.querySelector('#mpfilw input[data-k='+k+']').checked)"))
        check('the three places are drawn', sorted(names()) == ['Ally City', 'Enemy Town', 'Free Village'])
        pls = pg.evaluate("()=>{const r={};__app.mapV.leaflet.eachLayer(l=>{if(l.options&&l.options.halo&&l._map)r[l.options.tip.split(' · ')[0]]={w:l._radius*2}});return r}")
        check('three sizes: city bigger than town bigger than village %s' % {k: round(v['w'], 1) for k, v in pls.items()}, pls['Ally City']['w'] > pls['Enemy Town']['w'] > pls['Free Village']['w'])
        pg.evaluate("()=>document.querySelector('#mpocol').click()"); pg.wait_for_timeout(300)
        pls = pg.evaluate("()=>{const r={};__app.mapV.leaflet.eachLayer(l=>{if(l.options&&l.options.halo&&l._map){const g=l.pr.rg;r[l.options.tip.split(' · ')[0]]=g?g.options.color:''}});return r}")
        check('colour by owner: the allied city gets the blue ring, the enemy town the red one, the free village none %s' % pls, pls['Ally City'] in ('#4f8cff', '#38d6f2') and pls['Enemy Town'] in ('#ff5d5d', '#ff3b1e') and pls['Free Village'] == '')
        pg.evaluate("()=>document.querySelector('#mpocol').click()"); pg.wait_for_timeout(200)
        xy = pg.evaluate("()=>{let p=null;const m=__app.mapV.leaflet;m.eachLayer(l=>{if(l.options&&l.options.halo&&/^Ally City/.test(l.options.tip)){const q=m.latLngToContainerPoint(l.getLatLng()),b=m.getContainer().getBoundingClientRect();p=[b.left+q.x,b.top+q.y]}});return p}")
        pg.mouse.click(xy[0], xy[1]); pg.wait_for_timeout(500)
        check('a click on a place opens its window at once (no buildings, no zoom)', pg.locator('.mpop').count() == 1 and 'Ally City' in pg.inner_text('.mpop') and pg.evaluate("__app.mapV.leaflet.getZoom()") < 13)
        pg.evaluate("()=>document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}))")
        pg.evaluate("()=>document.querySelector('#mpobj a[data-a=pol]').click()"); pg.wait_for_timeout(500)
        check('the political button again: no place is drawn', names() == [])
        # airfields: the symbol is blue (ours or an ally's) or red (enemy) and stands in for the dot of the Airbases switch: a click on it opens the objective
        check('the scenario has an allied and an enemy airfield', ab['a'] and ab['e'])
        abcol = lambda i: pg.evaluate("i=>{let c=null;__app.mapV.leaflet.eachLayer(l=>{if(l.options&&l.options.icon&&/ico/.test(l.options.icon.options.className||'')&&l._tooltip&&l._tooltip._content.indexOf(i)==0){const m=(l.options.icon.options.html||'').match(/--c:([^\";]+)/);if(m)c=m[1]}});return c}", i)
        pre = lambda o: o[1][:6]
        check('allied airfield white on the dark map, enemy airfield red', abcol(pre(ab['a'])) == '#ffffff' and abcol(pre(ab['e'])) == '#ff5d5d')
        tog('o1', True); tog('o2', True); pg.wait_for_timeout(900)
        check('with the Airbases and Airstrips switches on no dot is drawn over an airfield symbol', names() == [])
        z0 = pg.evaluate("__app.mapV.leaflet.getZoom()")
        pg.evaluate("n=>{__app.mapV.leaflet.eachLayer(l=>{if(l.options&&l.options.icon&&/ico/.test(l.options.icon.options.className||'')&&l._tooltip&&l._tooltip._content.indexOf(n)==0)l.fire('click')})}", pre(ab['e'])); pg.wait_for_timeout(1200)
        check('a click on the airfield symbol (an airstrip too) opens the objective (the map zooms in on it)', pg.evaluate("__app.mapV.leaflet.getZoom()") >= 13 and pg.evaluate("__app.mapV.leaflet.getZoom()") > z0)
        tog('o1', False); tog('o2', False); pg.wait_for_timeout(500)
        # fixed radar stations: the owner decides (allies and neutral teams are not drawn, enemies red, unknown grey)
        pg.evaluate("o=>{window.__targetData={objectives:async()=>[],features:async x=>[],radars:async()=>[{o:{id:o.a,name:'Ally Radar',n:2800000,e:2300000,type:21},feats:[{k:0,n:2800000,e:2300000,det:75}]},{o:{id:o.e,name:'Enemy Radar',n:2900000,e:2200000,type:21},feats:[{k:0,n:2900000,e:2200000,det:75}]},{o:{id:o.n,name:'Neutral Radar',n:2600000,e:2450000,type:21},feats:[{k:0,n:2600000,e:2450000,det:75}]},{o:{id:999999,name:'Unknown Radar',n:2700000,e:2400000,type:21},feats:[{k:0,n:2700000,e:2400000,det:75}]}]}}", own)
        pg.evaluate("document.querySelector('#mpfilw input[data-k=rc]').click()"); pg.wait_for_timeout(3500)
        cols = sorted(pg.evaluate("(()=>{const r=[];__app.mapV.leaflet.eachLayer(l=>{if(l.options&&l.options.className=='rcov')r.push(l.options.color)});return r})()"))
        check('radar coverage: the allied and the neutral stations are left out, an enemy one is drawn red, the unknown one grey', len(cols) >= 2 and '#9aa4b2' in cols and any(c != '#9aa4b2' for c in cols) and len([c for c in cols if c == '#9aa4b2']) == 1)
        check('no page errors', not errs)
        br.close()
finally:
    srv.kill()
print('ALL OK' if ok else 'SOME FAILED'); sys.exit(0 if ok else 1)
